/// <summary>
/// PricingAttribute of table <c>RetailSalesLine</c> field Catalog.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::SalesLine, GUPPricingAttributeSourceLevel::Line)]
internal class GUPPricingAttributeRetailSalesLineCatalog extends GUPPricingAttributeRetailSalesLine implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(RetailSalesLine, Catalog);
}

public Set getAllowedValues()
{
    var             ret = new Set(Types::Int64);
    RetailSalesLine retailSalesLine;

    while select retailSalesLine
        group by Catalog
    {
        if (! ret.in(retailSalesLine.Catalog))
        {
            ret.add(retailSalesLine.Catalog);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailSalesLine, Catalog));
    qbr.value(queryValue(_value));
}
